        seen = set()
        queue = list(cnf)

        while queue:
            clause = queue.pop()
            for literal in clause:
                neg_literal = -literal
                if neg_literal in seen:
                    new_clause = [l for l in clause if l != literal and l != neg_literal]
                    if not new_clause:
                        return len(seen) + 1
                    new_clause = tuple(sorted(new_clause))
